initialize:
// Outils partagés par tous les flux (code « Au démarrage » du bloc).
//
// Rassemble ce que l'IHM garde en mémoire : l'état de l'automate, le journal,
// les sessions et les pages ouvertes (flux temps réel). Les autres
// blocs y accèdent par global.get("ihm").

const mm = global.get("mm");
const crypto = global.get("crypto");
const passwords = global.get("passwords");

const JOURNAL_SIZE = 500;
const COOKIE = "ihm_session";
const SESSION_MS = 8 * 3600 * 1000; // une session dure le temps d'un poste de travail

const USERS = {
    operateur: { role: "operator", password: passwords.operateur },
    admin: { role: "admin", password: passwords.admin },
};
const ROLE_LEVELS = { operator: 1, admin: 2 };

// Erreur renvoyée à la page avec son code HTTP (401 connexion requise, 403 accès insuffisant...).
function httpError(status, message) {
    const err = new Error(message);
    err.status = status;
    return err;
}

// Comparaison en temps constant, pour ne rien révéler du mot de passe.
function samePassword(a, b) {
    const hash = (s) => crypto.createHash("sha256").update(String(s)).digest();
    return crypto.timingSafeEqual(hash(a), hash(b));
}

const ihm = {
    mm,
    JOURNAL_SIZE,
    SESSION_MS,
    state: { connected: false },
    journal: [], // du plus récent au plus ancien
    startedAt: Date.now(),
    lastRead: 0, // heure de la dernière lecture réussie de l'automate
    lastAlarms: null, // alarmes lues au dernier cycle, pour détecter les changements
    lastEmergencyPress: null, // { user, time } : dernier AU enfoncé depuis l'IHM
    sessions: new Map(), // jeton -> { name, role, expires }
    sseClients: new Set(), // pages ouvertes, qui reçoivent l'état en temps réel

    httpError,

    addJournal(entry) {
        ihm.journal.unshift(entry);
        ihm.journal.length = Math.min(ihm.journal.length, JOURNAL_SIZE);
    },

    // Envoie l'état et le journal à toutes les pages ouvertes.
    broadcast() {
        const data = `data: ${JSON.stringify({ ...ihm.state, journal: ihm.journal })}\n\n`;
        for (const res of ihm.sseClients) res.write(data);
    },

    // Trace une action d'un utilisateur dans le journal.
    logAction(user, label) {
        ihm.addJournal({ time: Date.now(), label, event: "action", user: user ? user.name : "non connecté" });
        ihm.broadcast();
    },

    currentUser(req) {
        const token = req.cookies && req.cookies[COOKIE];
        const session = token && ihm.sessions.get(token);
        if (!session) return null;
        if (session.expires < Date.now()) {
            ihm.sessions.delete(token);
            return null;
        }
        return session;
    },

    // Renvoie l'utilisateur connecté s'il a au moins le niveau demandé.
    requireRole(req, role) {
        const user = ihm.currentUser(req);
        if (!user) throw httpError(401, "connexion requise");
        if (ROLE_LEVELS[user.role] < ROLE_LEVELS[role]) {
            throw httpError(403, role === "admin" ? "commande réservée à l'administrateur" : "accès insuffisant");
        }
        return user;
    },

    // Ouvre une session ; renvoie l'utilisateur et l'en-tête Set-Cookie à envoyer.
    login(username, password) {
        const account = Object.hasOwn(USERS, username) ? USERS[username] : null;
        // On compare même si le compte n'existe pas, pour ne pas révéler les identifiants valides.
        const ok = samePassword(password, account ? account.password : crypto.randomUUID()) && account;
        if (!ok) throw httpError(401, "identifiant ou mot de passe incorrect");
        const token = crypto.randomBytes(32).toString("hex");
        const user = { name: username, role: account.role, expires: Date.now() + SESSION_MS };
        ihm.sessions.set(token, user);
        const cookie = `${COOKIE}=${token}; HttpOnly; SameSite=Strict; Path=/; Max-Age=${SESSION_MS / 1000}`;
        return { user, cookie };
    },

    logout(req) {
        const token = req.cookies && req.cookies[COOKIE];
        if (token) ihm.sessions.delete(token);
        return `${COOKIE}=; HttpOnly; SameSite=Strict; Path=/; Max-Age=0`;
    },

    sessionInfo: (user) => (user ? { name: user.name, role: user.role } : null),

    // Prépare la réponse JSON au bloc « http response ».
    reply(msg, status, payload, headers = {}) {
        msg.statusCode = status;
        msg.headers = { "Content-Type": "application/json; charset=utf-8", ...headers };
        msg.payload = JSON.stringify(payload);
        return msg;
    },

    replyError(msg, err) {
        return ihm.reply(msg, err.status || 400, { ok: false, error: err.message });
    },
};

global.set("ihm", ihm);

finalize:
// Au redéploiement : ferme les flux temps réel des pages ouvertes, qui se
// reconnectent d'elles-mêmes au nouveau flux.
const ihm = global.get("ihm");
if (ihm) for (const res of ihm.sseClients) res.end();

func:
// Compare les alarmes avec celles du cycle précédent, alimente le journal et
// envoie le mail d'alerte à l'apparition de l'arrêt d'urgence. Puis diffuse
// l'état aux pages ouvertes.
const ihm = global.get("ihm");
const mm = ihm.mm;
const { alarms, time } = msg.payload;

if (ihm.lastAlarms) {
    alarms.forEach((a, i) => {
        const before = ihm.lastAlarms[i];
        const events = [];
        // Une cause brève (ex. défaut de rotation, coupé dès le cycle suivant) peut
        // passer entre deux lectures : sa mémorisation compte aussi comme apparition.
        // À l'inverse, disparition et acquittement peuvent tomber entre deux lectures.
        if ((a.active && !before.active) || (a.latched && !before.latched)) events.push("apparition");
        else {
            if (!a.active && before.active) events.push("disparition");
            if (!a.latched && before.latched) events.push("acquittement");
        }
        for (const event of events) ihm.addJournal({ time, label: a.label, event });
        if (events.includes("apparition") && i === mm.ALARM_EMERGENCY_STOP) sendEmergencyMail(time);
    });
} else {
    // Première lecture : on note les alarmes déjà présentes.
    alarms.forEach((a) => {
        if (a.active || a.latched) ihm.addJournal({ time, label: a.label, event: "présente au démarrage" });
    });
}
ihm.lastAlarms = alarms;
ihm.broadcast();
return null;

// --- Mail d'alerte sur arrêt d'urgence ---------------------------------------
// Déclenché par l'apparition de l'alarme, et non par le bouton de la page : un
// arrêt d'urgence venant d'ailleurs (client Modbus, bouton physique) est aussi signalé.
function emergencyMailText(time) {
    const dateTime = new Intl.DateTimeFormat("fr-FR", { dateStyle: "full", timeStyle: "medium" });
    const last = ihm.lastEmergencyPress;
    const press = last && time - last.time < 5000 ? last : null;
    const origin = press
        ? `depuis l'IHM (utilisateur : ${press.user})`
        : "hors de l'IHM (commande Modbus directe ou bouton externe)";
    const s = ihm.state;
    const lines = [
        "ALERTE : l'arrêt d'urgence de la ventilation a été déclenché.",
        "",
        `Date : ${dateTime.format(time)}`,
        `Origine : ${origin}`,
    ];
    if (s.connected) {
        lines.push(
            `Mode : ${s.summer ? "été" : "hiver"}`,
            `Température intérieure : ${s.t_int.toFixed(1)} °C`,
            `Température extérieure : ${s.t_ext.toFixed(1)} °C`
        );
    }
    lines.push(
        "",
        "Tous les ventilateurs sont arrêtés. Ils ne redémarreront qu'après le",
        "relâchement du bouton et un acquittement depuis l'IHM de supervision.",
        "",
        "-- Message automatique de l'IHM Ventilation Modbus"
    );
    return lines.join("\n");
}

function sendEmergencyMail(time) {
    global.get("alerts").sendToAll("[ALERTE] Arrêt d'urgence - Ventilation", emergencyMailText(time))
        .then((n) => ihm.addJournal({ time: Date.now(), label: `Mail d'alerte envoyé à ${n} destinataire(s)`, event: "mail" }))
        .catch((err) => ihm.addJournal({ time: Date.now(), label: `Mail d'alerte non envoyé : ${err.message}`, event: "mail" }))
        .finally(() => ihm.broadcast());
}

// Réunit les quatre lectures Modbus en un seul état, au format attendu par la
// page (public/index.html).
// msg.topic indique la lecture : coils (FC1), fans (FC2), holding (FC3), inputs (FC4).
const ihm = global.get("ihm");
const mm = global.get("mm");
const fromRegister = global.get("fromRegister");

const raw = context.get("raw") || {};
raw[msg.topic] = msg.payload;
context.set("raw", raw);

// On recalcule l'état à chaque lecture des capteurs et alarmes (FC4), une fois
// les trois autres lectures reçues au moins une fois.
const { coils, fans, holding, inputs } = raw;
if (msg.topic !== "inputs" || !coils || !fans || !holding) return null;

const coil = (address) => coils[address - mm.COILS_START];
const ir = (address) => inputs[address - mm.IR_SENSORS_START];
const hr = (address) => holding[address]; // lecture FC3 à partir de l'adresse 0
const setting = (address) => fromRegister(hr(address));

const FAN_MODE_NAMES = { [mm.FAN_MODE_AUTO]: "auto", [mm.FAN_MODE_MANUAL_ON]: "on", [mm.FAN_MODE_MANUAL_OFF]: "off" };
const FAN_MODE_REGISTERS = [mm.HR_FAN_MODE_1, mm.HR_FAN_MODE_2, mm.HR_FAN_MODE_3, mm.HR_FAN_MODE_4];
const FAN_FAULT_COILS = [mm.COIL_FAN_FAULT_1, mm.COIL_FAN_FAULT_2, mm.COIL_FAN_FAULT_3, mm.COIL_FAN_FAULT_4];
const fanAddresses = [mm.DI_FAN_1, mm.DI_FAN_2, mm.DI_FAN_3, mm.DI_FAN_4];
const active = ir(mm.IR_ALARMS_ACTIVE);
const latched = ir(mm.IR_ALARMS_LATCHED);

ihm.state = {
    connected: true,
    t_int: fromRegister(ir(mm.IR_T_INT)),
    t_ext: fromRegister(ir(mm.IR_T_EXT)),
    fans: fanAddresses.map((a) => fans[a - mm.DI_FANS_START]),
    summer: coil(mm.COIL_SUMMER_MODE),
    force_int: coil(mm.COIL_FORCE_T_INT),
    force_ext: coil(mm.COIL_FORCE_T_EXT),
    forced_int: fromRegister(hr(mm.HR_T_INT_FORCED)),
    forced_ext: fromRegister(hr(mm.HR_T_EXT_FORCED)),
    fan_modes: FAN_MODE_REGISTERS.map((a) => FAN_MODE_NAMES[hr(a)] || "auto"),
    emergency_stop: coil(mm.COIL_EMERGENCY_STOP),
    fan_faults: FAN_FAULT_COILS.map((a) => coil(a)),
    // Verrouillages de sécurité, déduits des alarmes mémorisées.
    emergency_lock: Boolean(latched & (1 << mm.ALARM_EMERGENCY_STOP)),
    fan_defects: [mm.ALARM_FAN_1, mm.ALARM_FAN_2, mm.ALARM_FAN_3, mm.ALARM_FAN_4].map((bit) => Boolean(latched & (1 << bit))),
    settings: {
        summer: [mm.HR_SUMMER_THRESHOLD_1, mm.HR_SUMMER_THRESHOLD_2, mm.HR_SUMMER_THRESHOLD_3].map(setting),
        winter: [mm.HR_WINTER_THRESHOLD_1, mm.HR_WINTER_THRESHOLD_2, mm.HR_WINTER_THRESHOLD_3].map(setting),
        winter_intake: setting(mm.HR_WINTER_INTAKE_THRESHOLD),
        hysteresis: setting(mm.HR_HYSTERESIS),
        t_int_high: setting(mm.HR_T_INT_HIGH_ALARM),
    },
    alarms: mm.ALARM_LABELS.map((label, bit) => ({
        label,
        active: Boolean(active & (1 << bit)),
        latched: Boolean(latched & (1 << bit)),
    })),
    time: Date.now(),
};
ihm.lastRead = ihm.state.time;
node.status({ fill: "green", shape: "dot", text: `T_int ${ihm.state.t_int.toFixed(1)} °C` });
msg.payload = ihm.state;
return msg;

// Chaque seconde : sans lecture réussie depuis 2 s, l'automate est déclaré
// injoignable, et les pages affichent la perte de liaison.
const ihm = global.get("ihm");
if (Date.now() - ihm.lastRead > 2000) {
    if (ihm.state.connected) node.warn("Automate injoignable, nouvelle tentative...");
    ihm.state = { connected: false, error: "automate injoignable" };
    ihm.broadcast();
    node.status({ fill: "red", shape: "ring", text: "automate injoignable" });
} else {
    node.status({ fill: "green", shape: "dot", text: "liaison OK" });
}
return null;

// Envoie une à une les écritures préparées par la commande (msg.writes) au bloc
// « Écrire dans l'automate », qui renvoie ici après chaque écriture réussie.
// Quand tout est écrit : trace les actions au journal et répond à la page.
// Sortie 1 : écriture Modbus suivante. Sortie 2 : réponse à la page.
const ihm = global.get("ihm");

if (msg.error) {
    // Échec d'une écriture, remonté par le bloc « catch ».
    return [null, ihm.reply(msg, 400, { ok: false, error: msg.error.message || "écriture refusée par l'automate" })];
}
if (msg.writes.length) {
    if (!ihm.state.connected) return [null, ihm.reply(msg, 400, { ok: false, error: "automate injoignable" })];
    msg.payload = { ...msg.writes.shift(), unitid: ihm.mm.DEVICE_ID };
    return [msg, null];
}
for (const label of msg.actions) ihm.logAction(msg.user, label);
return [null, ihm.reply(msg, 200, { ok: true })];

// POST api/mode { summer } : passage en mode été / hiver (opérateur).
// Sortie 1 : écritures Modbus à faire. Sortie 2 : réponse d'erreur à la page.
const ihm = global.get("ihm");
const mm = ihm.mm;
try {
    msg.user = ihm.requireRole(msg.req, "operator");
    const { summer } = msg.payload;
    if (typeof summer !== "boolean") throw new Error("'summer' doit etre true ou false");
    msg.writes = [{ fc: 5, address: mm.COIL_SUMMER_MODE, quantity: 1, value: summer }];
    msg.actions = [summer ? "Passage en mode été" : "Passage en mode hiver"];
    return [msg, null];
} catch (err) {
    return [null, ihm.replyError(msg, err)];
}

// POST api/force { t_int?, t_ext? } : forçage d'une température, ou relâchement
// avec null (administrateur).
const ihm = global.get("ihm");
const mm = ihm.mm;
const toRegister = global.get("toRegister");
const T_MIN = -50;
const T_MAX = 100;

function checkTemperature(value) {
    if (value === null) return null;
    if (typeof value !== "number" || !Number.isFinite(value) || value < T_MIN || value > T_MAX) {
        throw new Error(`temperature invalide (attendu un nombre entre ${T_MIN} et ${T_MAX}, ou null)`);
    }
    return value;
}

// Valeur -> registre de forçage puis coil à true ; null -> coil à false.
function force(name, coil, register, value) {
    if (value !== null) msg.writes.push({ fc: 6, address: register, quantity: 1, value: toRegister(value) });
    msg.writes.push({ fc: 5, address: coil, quantity: 1, value: value !== null });
    msg.actions.push(value === null ? `Forçage ${name} relâché` : `Forçage ${name} à ${value.toFixed(1)} °C`);
}

try {
    msg.user = ihm.requireRole(msg.req, "admin");
    const body = msg.payload;
    msg.writes = [];
    msg.actions = [];
    if ("t_int" in body) force("T_int", mm.COIL_FORCE_T_INT, mm.HR_T_INT_FORCED, checkTemperature(body.t_int));
    if ("t_ext" in body) force("T_ext", mm.COIL_FORCE_T_EXT, mm.HR_T_EXT_FORCED, checkTemperature(body.t_ext));
    return [msg, null];
} catch (err) {
    return [null, ihm.replyError(msg, err)];
}

// POST api/fan-mode { fan, mode } : mode auto / marche / arrêt d'un ventilateur (opérateur).
const ihm = global.get("ihm");
const mm = ihm.mm;
const FAN_MODES = { auto: mm.FAN_MODE_AUTO, on: mm.FAN_MODE_MANUAL_ON, off: mm.FAN_MODE_MANUAL_OFF };
const FAN_MODE_LABELS = { auto: "auto", on: "manuel marche", off: "manuel arrêt" };
const FAN_MODE_REGISTERS = [mm.HR_FAN_MODE_1, mm.HR_FAN_MODE_2, mm.HR_FAN_MODE_3, mm.HR_FAN_MODE_4];
try {
    msg.user = ihm.requireRole(msg.req, "operator");
    const { fan, mode } = msg.payload;
    if (!(mode in FAN_MODES)) throw new Error("'mode' doit valoir auto, on ou off");
    if (![1, 2, 3, 4].includes(fan)) throw new Error("'fan' doit valoir 1, 2, 3 ou 4");
    msg.writes = [{ fc: 6, address: FAN_MODE_REGISTERS[fan - 1], quantity: 1, value: FAN_MODES[mode] }];
    msg.actions = [`V${fan} en mode ${FAN_MODE_LABELS[mode]}`];
    return [msg, null];
} catch (err) {
    return [null, ihm.replyError(msg, err)];
}

// POST api/emergency-stop { pressed } : enfonce ou relâche l'arrêt d'urgence.
// Accessible sans connexion : un arrêt d'urgence ne doit jamais être bloqué.
// Le relâcher ne relance rien : le réarmement passe par l'acquittement.
const ihm = global.get("ihm");
const mm = ihm.mm;
try {
    const { pressed } = msg.payload;
    if (typeof pressed !== "boolean") throw new Error("'pressed' doit etre true ou false");
    msg.user = ihm.currentUser(msg.req);
    // Noté pour le mail d'alerte, qui indique qui a déclenché l'arrêt.
    if (pressed) ihm.lastEmergencyPress = { user: msg.user ? msg.user.name : "non connecté", time: Date.now() };
    msg.writes = [{ fc: 5, address: mm.COIL_EMERGENCY_STOP, quantity: 1, value: pressed }];
    msg.actions = [pressed ? "Arrêt d'urgence enfoncé" : "Arrêt d'urgence relâché"];
    return [msg, null];
} catch (err) {
    return [null, ihm.replyError(msg, err)];
}

// POST api/ack : acquittement des alarmes (opérateur). Impulsion remise à
// false par l'automate.
const ihm = global.get("ihm");
const mm = ihm.mm;
try {
    msg.user = ihm.requireRole(msg.req, "operator");
    msg.writes = [{ fc: 5, address: mm.COIL_ACK, quantity: 1, value: true }];
    msg.actions = ["Acquittement demandé"];
    return [msg, null];
} catch (err) {
    return [null, ihm.replyError(msg, err)];
}

// POST api/fan-fault { fan, fault } : panne moteur simulée (administrateur).
const ihm = global.get("ihm");
const mm = ihm.mm;
const FAN_FAULT_COILS = [mm.COIL_FAN_FAULT_1, mm.COIL_FAN_FAULT_2, mm.COIL_FAN_FAULT_3, mm.COIL_FAN_FAULT_4];
try {
    msg.user = ihm.requireRole(msg.req, "admin");
    const { fan, fault } = msg.payload;
    if (![1, 2, 3, 4].includes(fan)) throw new Error("'fan' doit valoir 1, 2, 3 ou 4");
    if (typeof fault !== "boolean") throw new Error("'fault' doit etre true ou false");
    msg.writes = [{ fc: 5, address: FAN_FAULT_COILS[fan - 1], quantity: 1, value: fault }];
    msg.actions = [`Panne simulée V${fan} ${fault ? "activée" : "retirée"}`];
    return [msg, null];
} catch (err) {
    return [null, ihm.replyError(msg, err)];
}

// POST api/settings : tous les réglages en une seule écriture (FC16), car
// l'automate vérifie la cohérence de l'ensemble (administrateur).
const ihm = global.get("ihm");
const mm = ihm.mm;
const toRegister = global.get("toRegister");

// Registre, libellé du journal, et lecture dans l'objet échangé avec la page
// { summer: [v1, v2, v3], winter: [...], winter_intake, hysteresis, t_int_high }.
const SETTINGS = [
    ...[1, 2, 3].map((n) => ({ address: mm[`HR_SUMMER_THRESHOLD_${n}`], label: `Seuil V${n} été`, get: (s) => s.summer[n - 1] })),
    ...[1, 2, 3].map((n) => ({ address: mm[`HR_WINTER_THRESHOLD_${n}`], label: `Seuil V${n} hiver`, get: (s) => s.winter[n - 1] })),
    { address: mm.HR_WINTER_INTAKE_THRESHOLD, label: "Seuil insufflation V4 hiver", get: (s) => s.winter_intake },
    { address: mm.HR_HYSTERESIS, label: "Hystérésis", get: (s) => s.hysteresis },
    { address: mm.HR_T_INT_HIGH_ALARM, label: "Seuil alarme haute", get: (s) => s.t_int_high },
];

// Mêmes règles que Settings.errors() dans automate.py : on les vérifie ici pour
// répondre un message clair, l'automate refusant de toute façon un réglage incohérent.
function checkSettings(body) {
    const isNumber = (v) => typeof v === "number" && Number.isFinite(v);
    const inRange = (v, min, max) => isNumber(v) && v >= min && v <= max;
    const s = {
        summer: body.summer,
        winter: body.winter,
        winter_intake: body.winter_intake,
        hysteresis: body.hysteresis,
        t_int_high: body.t_int_high,
    };
    for (const season of ["summer", "winter"]) {
        const name = season === "summer" ? "été" : "hiver";
        const v = s[season];
        if (!Array.isArray(v) || v.length !== 3 || !v.every((t) => inRange(t, mm.SETPOINT_MIN, mm.SETPOINT_MAX))) {
            throw new Error(`seuils ${name} : 3 valeurs entre ${mm.SETPOINT_MIN} et ${mm.SETPOINT_MAX} °C attendues`);
        }
        if (!(v[0] <= v[1] && v[1] <= v[2])) throw new Error(`seuils ${name} : il faut V1 ≤ V2 ≤ V3`);
    }
    for (const [key, name] of [["winter_intake", "seuil insufflation V4 hiver"], ["t_int_high", "seuil alarme haute"]]) {
        if (!inRange(s[key], mm.SETPOINT_MIN, mm.SETPOINT_MAX)) {
            throw new Error(`${name} : valeur entre ${mm.SETPOINT_MIN} et ${mm.SETPOINT_MAX} °C attendue`);
        }
    }
    if (!inRange(s.hysteresis, mm.HYSTERESIS_MIN, mm.HYSTERESIS_MAX)) {
        throw new Error(`hystérésis : valeur entre ${mm.HYSTERESIS_MIN} et ${mm.HYSTERESIS_MAX} °C attendue`);
    }
    // Arrondi au dixième, la précision des registres.
    const round = (v) => Math.round(v * mm.TEMPERATURE_SCALE) / mm.TEMPERATURE_SCALE;
    return {
        summer: s.summer.map(round),
        winter: s.winter.map(round),
        winter_intake: round(s.winter_intake),
        hysteresis: round(s.hysteresis),
        t_int_high: round(s.t_int_high),
    };
}

try {
    msg.user = ihm.requireRole(msg.req, "admin");
    if (!ihm.state.connected) throw new Error("automate injoignable");
    const settings = checkSettings(msg.payload);
    const before = ihm.state.settings;
    const values = new Array(mm.HR_SETTINGS_COUNT).fill(0);
    for (const s of SETTINGS) values[s.address - mm.HR_SETTINGS_START] = toRegister(s.get(settings));
    msg.writes = [{ fc: 16, address: mm.HR_SETTINGS_START, quantity: mm.HR_SETTINGS_COUNT, value: values }];
    msg.actions = SETTINGS.filter((s) => s.get(settings) !== s.get(before))
        .map((s) => `${s.label} : de ${s.get(before).toFixed(1)} à ${s.get(settings).toFixed(1)} °C`);
    return [msg, null];
} catch (err) {
    return [null, ihm.replyError(msg, err)];
}

// POST api/settings/defaults : retour aux réglages par défaut (administrateur).
// L'automate connaît seul les valeurs par défaut : on lui envoie la commande,
// une impulsion qu'il remet à false.
const ihm = global.get("ihm");
const mm = ihm.mm;
try {
    msg.user = ihm.requireRole(msg.req, "admin");
    if (!ihm.state.connected) throw new Error("automate injoignable");
    msg.writes = [{ fc: 5, address: mm.COIL_RESTORE_DEFAULTS, quantity: 1, value: true }];
    msg.actions = ["Retour aux réglages par défaut"];
    return [msg, null];
} catch (err) {
    return [null, ihm.replyError(msg, err)];
}

// Sert les pages de l'IHM (public/).
const fs = global.get("fs");
const path = global.get("path");
const FILES = {
    "/": ["index.html", "text/html; charset=utf-8"],
    "/alertes": ["alertes.html", "text/html; charset=utf-8"],
    "/common.css": ["common.css", "text/css; charset=utf-8"],
};
// Les pages utilisent des adresses relatives : la supervision doit être
// ouverte avec la barre finale (/ihm/ et non /ihm).
const url = msg.req.originalUrl.split("?")[0];
if (msg.req.route.path === "/" && !url.endsWith("/")) {
    msg.statusCode = 301;
    msg.headers = { Location: url + "/" };
    msg.payload = "";
    return msg;
}
const [file, type] = FILES[msg.req.route.path];
msg.statusCode = 200;
msg.headers = { "Content-Type": type, "Cache-Control": "no-cache" };
msg.payload = fs.readFileSync(path.join(global.get("publicDir"), file), "utf8");
return msg;

// GET events : flux temps réel (Server-Sent Events). La connexion reste
// ouverte, et « Outils partagés » y écrit l'état à chaque lecture de l'automate.
const ihm = global.get("ihm");
const res = msg.res._res;
res.writeHead(200, {
    "Content-Type": "text/event-stream",
    "Cache-Control": "no-cache",
    Connection: "keep-alive",
});
res.write(`data: ${JSON.stringify({ ...ihm.state, journal: ihm.journal })}\n\n`);
ihm.sseClients.add(res);
msg.req.on("close", () => ihm.sseClients.delete(res));
node.status({ text: `${ihm.sseClients.size} page(s) ouverte(s)` });
return null;

// GET api/session : utilisateur connecté, ou null.
const ihm = global.get("ihm");
return ihm.reply(msg, 200, { ok: true, user: ihm.sessionInfo(ihm.currentUser(msg.req)) });

// POST api/login { username, password } : ouvre une session (cookie).
const ihm = global.get("ihm");
try {
    const { username, password } = msg.payload || {};
    const { user, cookie } = ihm.login(String(username || ""), String(password || ""));
    ihm.logAction(user, "Connexion");
    return ihm.reply(msg, 200, { ok: true, user: ihm.sessionInfo(user) }, { "Set-Cookie": cookie });
} catch (err) {
    return ihm.replyError(msg, err);
}

// POST api/logout : ferme la session.
const ihm = global.get("ihm");
const user = ihm.currentUser(msg.req);
const cookie = ihm.logout(msg.req);
if (user) ihm.logAction(user, "Déconnexion");
return ihm.reply(msg, 200, { ok: true }, { "Set-Cookie": cookie });

// GET api/report.pdf : rapport d'alarmes en PDF (opérateur), produit par
// report.js.
const ihm = global.get("ihm");
let user;
try {
    user = ihm.requireRole(msg.req, "operator");
} catch (err) {
    return ihm.replyError(msg, err);
}
const res = msg.res._res;
const stamp = new Date().toISOString().slice(0, 16).replace("T", "_").replace(":", "h");
res.writeHead(200, {
    "Content-Type": "application/pdf",
    "Content-Disposition": `attachment; filename="rapport-alarmes_${stamp}.pdf"`,
});
global.get("writeReport")(res, {
    state: ihm.state,
    journal: ihm.journal,
    startedAt: ihm.startedAt,
    user,
    journalSize: ihm.JOURNAL_SIZE,
});
return null;

// Alertes par mail (administrateur) : destinataires et compte d'envoi, gérés
// par alerts.js (enregistrés dans nodered/data).
// msg.req.route.path indique la demande.
const ihm = global.get("ihm");
const alerts = global.get("alerts");
const route = msg.req.route.path;
const body = msg.payload || {};

async function handle() {
    const user = ihm.requireRole(msg.req, "admin"); // adresses personnelles : visibles par l'admin seulement
    switch (`${msg.req.method} ${route}`) {
        case "GET /api/alert-emails":
            return { ok: true, emails: alerts.getEmails(), account: alerts.accountStatus() };
        case "POST /api/alert-emails": {
            const email = alerts.addEmail(body.email);
            ihm.logAction(user, `Destinataire d'alerte ajouté : ${email}`);
            return { ok: true, emails: alerts.getEmails() };
        }
        case "POST /api/alert-emails/delete": {
            const email = alerts.removeEmail(body.email);
            ihm.logAction(user, `Destinataire d'alerte retiré : ${email}`);
            return { ok: true, emails: alerts.getEmails() };
        }
        case "POST /api/mail-account": {
            const result = await alerts.setAccount(body);
            ihm.logAction(user, `Compte d'envoi des alertes : ${result.user}`);
            return { ok: true, account: alerts.accountStatus() };
        }
        case "POST /api/mail-account/delete":
            alerts.clearAccount();
            ihm.logAction(user, "Compte d'envoi des alertes supprimé");
            return { ok: true, account: alerts.accountStatus() };
        case "POST /api/alert-emails/test": {
            const n = await alerts.sendToAll(
                "[TEST] Alerte Ventilation",
                `Mail de test envoyé depuis l'IHM par ${user.name}.\n\n` +
                    "Ces adresses recevront un mail d'alerte à chaque arrêt d'urgence.\n\n" +
                    "-- Message automatique de l'IHM Ventilation Modbus"
            );
            ihm.logAction(user, `Mail de test envoyé à ${n} destinataire(s)`);
            return { ok: true, sent: n };
        }
    }
    throw ihm.httpError(404, "introuvable");
}

handle()
    .then((payload) => node.send(ihm.reply(msg, 200, payload)))
    .catch((err) => node.send(ihm.replyError(msg, err)));
return null;
